(() => {
  'use strict';
  const DATA = window.OS_DATA;
  if (!DATA) {
    document.getElementById('app').innerHTML = '<main style="padding:40px"><h1>Orienta&#39;Sion by CNEF</h1><p>Le contenu n’a pas pu être chargé. Rechargez la page.</p></main>';
    return;
  }
  const paths = {
    compass:'M12 3l2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3Z M12 8v8',
    search:'m21 21-4.4-4.4 M19 10.5a8.5 8.5 0 1 1-17 0 8.5 8.5 0 0 1 17 0',
    book:'M12 6c-3-2-6-2-10-1v14c4-1 7-1 10 1 3-2 6-2 10-1V5c-4-1-7-1-10 1Z M12 6v14',
    building:'M4 21V8l8-5 8 5v13 M2 21h20 M8 11v3 M12 11v3 M16 11v3 M9 21v-4h6v4',
    check:'m5 12 4 4L19 6',
    list:'M9 6h12 M9 12h12 M9 18h12 M3 6h.01 M3 12h.01 M3 18h.01',
    cap:'m2 9 10-5 10 5-10 5L2 9Z M6 11v6c4 3 8 3 12 0v-6 M22 9v7',
    bookmark:'M6 3h12v18l-6-4-6 4V3Z',
    users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M16 3.1a4 4 0 0 1 0 7.8',
    user:'M20 21v-2a7 7 0 0 0-14 0v2 M17 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
    pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
    clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',
    globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M2 12h20 M12 2c5 5 5 15 0 20-5-5-5-15 0-20',
    compare:'M5 3v18 M19 3v18 M2 8h6 M16 16h6 M9 8h5 M10 16h5',
    plus:'M12 5v14 M5 12h14',
    close:'m6 6 12 12 M6 18 18 6',
    chevron:'m7 10 5 5 5-5',
    info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7h.01',
    external:'M15 3h6v6 M10 14 21 3 M21 13v7a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h7',
    chat:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z',
    menu:'M3 6h18 M3 12h18 M3 18h18',
    home:'m3 10 9-7 9 7v11h-7v-7h-4v7H3V10Z',
    spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',
    wallet:'M20 7H4a2 2 0 0 1 0-4h15v4 M4 7a2 2 0 0 1-2-2v14a2 2 0 0 0 2 2h17V7 M16 11h6v6h-6v-6Z M18.5 14h.01',
    heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',
    print:'M6 9V3h12v6 M6 17H3V9h18v8h-3 M6 14h12v8H6V14Z M17 11h.01',
    shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-4Z m-4 10 3 3 5-6',
    calendar:'M4 5h16v17H4V5Z M16 2v6 M8 2v6 M4 11h16',
    language:'M3 5h12 M9 3v2 M5 5c0 6 7 10 7 10 M13 5c0 6-7 10-10 10 M13 21l4-11 4 11 M15 17h4',
    file:'M14 2H4v20h16V8l-6-6Z M14 2v6h6 M8 13h8 M8 17h6'
  };
  const icon = (name,cls='') => `<svg ${cls ? `class="${cls}"` : ''} viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.book}"></path></svg>`;
  const h = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normal = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’'\-–—]/g,' ').replace(/\s+/g,' ').trim();
  const readStore = (key,fallback) => {try {const v=JSON.parse(localStorage.getItem('os-'+key));return v ?? fallback;}catch{return fallback;}};
  const writeStore = (key,value) => {try{localStorage.setItem('os-'+key,JSON.stringify(value));}catch{}};
  const validIds = new Set(DATA.courses.map(c=>c.id));
  const storedArray = key => {const v=readStore(key,[]);return Array.isArray(v) ? v.filter(id=>validIds.has(id)) : [];};
  const favorites = new Set(storedArray('favorites'));
  let comparison = storedArray('comparison').slice(0,3);
  let audience=readStore('audience','student')==='parent'?'parent':'student';
  let route='etablissements', glossaryQuery='', glossaryCategory='', activeCourse=null, activeTab='course';
  const emptyFilters=()=>({q:'',type:'',city:'',language:'',domain:'',subtype:'',scope:'postbac',institution:''});
  const catalogueFilters={explorer:emptyFilters(),favoris:emptyFilters(),etablissements:emptyFilters()};
  let filters=catalogueFilters.explorer;
  const routes={explorer:'Les cursus',etablissements:'Les établissements',admissions:'Les admissions',mehinot:'Les mehinot',glossaire:'Le glossaire',parents:'L’espace parents',favoris:'Mes favoris'};
  const getInst = id => DATA.institutions.find(i=>i.id===id);
  const places = i => i.locations||[i.city];
  const getCourse = id => DATA.courses.find(c=>c.id===id);
  const source = (url,label='Consulter la source officielle') => /^https:\/\//.test(url||'') ? `<a class="source-link" href="${h(url)}" target="_blank" rel="noopener noreferrer">${h(label)} ${icon('external')}</a>` : '<span class="footnote">Source à compléter</span>';
  function institutionTone(inst){return inst.subtype==='Formation des enseignants'?'green':inst.kind==='Université'?'blue':'orange';}
  function instStyle(inst){const colors={blue:'#025db8',orange:'#a83c00',green:'#1d8653'},color=colors[institutionTone(inst)];return `--inst-color:${color};--inst-bg:${color}10`;}

  function monogram(inst){return `<span class="inst-monogram" data-tone="${institutionTone(inst)}" style="${instStyle(inst)}">${h(inst.initials||inst.short)}</span>`;}
  function footer(){return `<footer class="footer"><span>Orienta'Sion by CNEF · Première ébauche · Novembre 2026</span><span>${icon('shield')} Les sources sont accessibles dans chaque fiche.</span></footer>`;}
  function notice(){const meta=getInst(filters.institution)?.courseCoverage;if(route==='explorer'&&meta)return `<div class="notice">${icon('info')}<span>Parcours et options recensés pour ${h(meta.academicYear)}. L’admission avec un bac français et l’ouverture à la rentrée visée restent à vérifier pour chaque parcours.</span></div>`;return `<div class="notice">${icon('info')}<span>${route==='etablissements'?'Recensement rapproché des sources officielles de 2026. Les campus et les conditions d’accès se vérifient pour chaque cursus.':'Les cursus détaillés restent un échantillon. Critères d’admission, tarifs et calendriers à confirmer pour la rentrée visée.'}</span></div>`;}
  function heroArt(){
    const dots=Array.from({length:16},(_,n)=>`<circle cx="${250+(n%4)*23}" cy="${164+Math.floor(n/4)*23}" r="10.5"/>`).join('');
    const sun=Array.from({length:48},(_,n)=>{const a=n*Math.PI/24,r=n%2?43:53;return `${(270+Math.cos(a)*r).toFixed(1)},${(73+Math.sin(a)*r).toFixed(1)}`;}).join(' ');
    return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 400 280" xmlns="http://www.w3.org/2000/svg"><g fill="#f8cf3e"><path d="M156 38a47 47 0 0 0 0 94Z"/><path d="M203 38a47 47 0 0 0 0 94Z"/></g><polygon points="${sun}" fill="#f55700"/><path d="m270 49 7 17 17 7-17 7-7 17-7-17-17-7 17-7Z" fill="#fff9f2"/><g transform="translate(108 138) rotate(-8 55 49)"><rect width="110" height="98" rx="20" fill="#1d8653"/><path d="m21 37 34-17 34 17-34 17-34-17Zm12 7v24c14 9 30 9 44 0V44M89 37v30" fill="none" stroke="#fff9f2" stroke-width="3" stroke-linejoin="round"/></g><g fill="#025db8">${dots}</g></svg><span class="hero-badge">${icon('compass')} À chacun son chemin</span></div>`;
  }
  function cnefLogo(){return '<img class="cnef-logo" src="assets/cnef-logo.webp" alt="CNEF" width="290" height="128" decoding="async">';}
  function shell(){
    const links=[['etablissements','building','Les établissements','blue'],['explorer','compass','Explorer les cursus','blue'],['admissions','file','Les admissions','orange'],['mehinot','cap','Les mehinot','green'],['glossaire','book','Le glossaire','yellow']];
    document.getElementById('app').innerHTML=`<button class="menu-backdrop" data-action="close-menu" aria-label="Fermer le menu"></button><aside class="sidebar" aria-label="Navigation principale"><a class="brand" href="#etablissements" aria-label="Orienta'Sion by CNEF, accueil"><span class="brand-icon">${icon('compass')}</span><span class="brand-wordmark"><span class="brand-title">Orienta'Sion</span><span class="brand-by"><span>by</span><span class="cnef-logo-tile">${cnefLogo()}</span></span><span class="brand-sub">TROUVER SA VOIE</span></span></a><div class="nav-label">Mon orientation</div><nav class="nav">${links.map(([id,ic,label,tone])=>`<a class="nav-link ${route===id?'active':''}" href="#${id}" data-tone="${tone}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}<div class="nav-divider"></div><a class="nav-link ${route==='parents'?'active':''}" href="#parents" data-tone="green" ${route==='parents'?'aria-current="page"':''}>${icon('users')}<span>Espace parents</span></a><a class="nav-link ${route==='favoris'?'active':''}" href="#favoris" data-tone="orange" ${route==='favoris'?'aria-current="page"':''}>${icon('bookmark')}<span>Mes favoris</span><span class="nav-count" id="favorite-count">${favorites.size}</span></a></nav><div class="sidebar-bottom"><div class="sidebar-note"><strong>Un projet qui se construit.</strong>Des repères pour choisir.<br>Des personnes pour avancer.</div><div class="sidebar-version">${icon('compass')} Première ébauche</div></div></aside><div class="workspace"><header class="topbar"><button class="mobile-toggle" data-action="toggle-menu" aria-label="Ouvrir le menu" aria-expanded="false">${icon('menu')}</button><a class="mobile-brand" href="#etablissements" aria-label="Orienta'Sion by CNEF, accueil"><span>Orienta'Sion</span><small class="mobile-endorsement">by ${cnefLogo()}</small></a><div class="breadcrumb">${icon('home')}<span class="breadcrumb-prefix">Le guide post-bac en Israël&nbsp; / &nbsp;</span><strong>${h(routes[route])}</strong></div><div class="audience-switch" aria-label="Votre profil"><button data-action="audience" data-value="student" class="${audience==='student'?'selected':''}" aria-pressed="${audience==='student'}">${icon('cap')} Futur étudiant</button><button data-action="audience" data-value="parent" class="${audience==='parent'?'selected':''}" aria-pressed="${audience==='parent'}">${icon('users')} Parent</button></div></header><main id="main" class="main" tabindex="-1"></main></div><div id="comparison-area"></div>`;
    renderPage();renderCompareBar();
  }
  function renderPage(){
    document.body.dataset.section=route;
    const main=document.getElementById('main');
    if(['explorer','favoris','etablissements'].includes(route)) main.innerHTML=cataloguePage();
    else if(route==='glossaire') main.innerHTML=glossaryPage();
    else if(route==='admissions') main.innerHTML=admissionsPage();
    else if(route==='mehinot') main.innerHTML=prepsPage();
    else if(route==='parents') main.innerHTML=parentsPage();
    if(['explorer','favoris','etablissements'].includes(route)) updateCatalogue();
    if(route==='glossaire')updateGlossary();
    if(route==='parents')updateBudget();
  }
  function filterSelect(name,label,values){return `<div class="select-wrap"><select name="${h(name)}" data-filter="${h(name)}" aria-label="${h(label)}"><option value="">${h(label)}</option>${values.map(v=>`<option ${filters[name]===v?'selected':''} value="${h(v)}">${h(v)}</option>`).join('')}</select>${icon('chevron')}</div>`;}
  function institutionSelect(){const ids=new Set(DATA.courses.map(c=>c.institution));return `<div class="select-wrap institution-select"><select data-filter="institution" aria-label="Établissement des cursus"><option value="">Tous les établissements</option>${DATA.institutions.filter(i=>ids.has(i.id)).sort((a,b)=>a.short.localeCompare(b.short,'fr')).map(i=>`<option value="${h(i.id)}" ${filters.institution===i.id?'selected':''}>${h(i.short)}</option>`).join('')}</select>${icon('chevron')}</div>`;}
  function institutionCatalogueBanner(){const i=getInst(filters.institution);if(!i)return '';const meta=i.courseCoverage;return `<section class="institution-catalogue-banner">${monogram(i)}<div><h2>${h(i.name)}</h2><p>${meta?`${DATA.courses.filter(c=>c.institution===i.id).length} parcours et options · ${h(meta.academicYear)}`:'Les cursus actuellement documentés dans l’application'}</p></div><button class="button secondary" data-action="institution" data-id="${h(i.id)}">Périmètre et sources</button></section>`;}
  function inScope(i){return filters.scope==='all'||(filters.scope==='advanced'?i.postbac===false:i.postbac!==false);}
  function scopeSelect(){return `<div class="select-wrap"><select data-filter="scope" aria-label="Niveau d’études"><option value="postbac" ${filters.scope==='postbac'?'selected':''}>Avec premier cycle / post-bac</option><option value="all" ${filters.scope==='all'?'selected':''}>Tous les établissements</option><option value="advanced" ${filters.scope==='advanced'?'selected':''}>Cycles supérieurs uniquement</option></select>${icon('chevron')}</div>`;}
  function directorySummary(){const groups=[['Université','Universités','building'],['Mihlala académique','Mihlalot académiques','cap'],['Formation des enseignants','Formation des enseignants','book']];return groups.map(([kind,label,ic])=>{const n=DATA.institutions.filter(i=>inScope(i)&&i.subtype===kind).length;const display=n===1&&kind!=='Formation des enseignants'?kind:label;return `<button class="directory-stat ${filters.subtype===kind?'active':''}" data-tone="${institutionTone({subtype:kind,kind:kind})}" data-action="institution-category" data-value="${h(kind)}" aria-pressed="${filters.subtype===kind}"><span class="stat-icon">${icon(ic)}</span><span><strong>${n}</strong><span>${display}</span></span></button>`;}).join('');}
  function coveragePanel(){const meta=DATA.catalogueMeta;if(!meta)return '';const first=DATA.institutions.filter(i=>i.postbac!==false).length;return `<details class="coverage-panel"><summary>Périmètre, sources et changements de nom</summary><div><p><strong>${DATA.institutions.length} fiches établissements, dont ${first} avec premier cycle.</strong> Le repère officiel du CHE pour 2026–2027 est de ${h(meta.officialExpectedTotal)} établissements, tous cycles confondus. Le catalogue applique une sélection éditoriale à partir de ce périmètre. Le rapprochement repose sur les publications officielles et les sites des établissements ; il ne constitue pas un export certifié du registre.</p><p>Les établissements issus d’une fusion apparaissent une seule fois. Leurs anciens noms restent recherchables. Weizmann et Schechter sont consultables dans « Tous les établissements », avec la mention de leur périmètre hors post-bac.</p><p>Les catégories affichées sont des repères de navigation. Le classement statistique peut différer, notamment lors d’un changement de statut. Les implantations indiquées sont des repères géographiques ; le campus du cursus choisi reste à vérifier.</p><p>Sources consultées le 24 novembre 2026. Les cursus et leurs critères sont documentés séparément.</p>${source(meta.registrySource,'Consulter le repère officiel du CHE')}</div></details>`;}
  function cataloguePage(){
    const inst=route==='etablissements', fav=route==='favoris',selectedInstitution=getInst(filters.institution);
    const intro=inst?`<section class="hero directory-hero"><div class="hero-copy"><div class="eyebrow">${icon('building')} LE GUIDE POST-BAC EN ISRAËL</div><h1 class="site-title">Orienta'Sion <span class="site-endorsement">by ${cnefLogo()}</span></h1><p class="hero-tagline">Votre avenir en Israël<br><em>commence ici.</em></p><p>Universités et mihlalot : explorez les établissements et trouvez les repères pour construire votre projet.</p></div>${heroArt()}</section><div class="directory-summary" id="directory-summary" aria-label="Types d’établissements">${directorySummary()}</div>${coveragePanel()}`:fav?`<div class="page-heading"><div class="eyebrow">${icon('bookmark')} VOTRE SÉLECTION</div><h1>Les pistes que vous gardez en tête.</h1><p>Retrouvez vos cursus favoris et comparez-les à votre rythme. Votre sélection reste enregistrée sur cet appareil.</p></div>`:selectedInstitution?`<div class="page-heading"><div class="eyebrow">${icon('cap')} LES POSSIBILITÉS APRÈS LE BAC</div><h1>${h(selectedInstitution.short)} : les parcours.</h1><p>Explorez les formations, les combinaisons entre disciplines et les options. Chaque fiche précise le diplôme, la durée et la source officielle.</p></div>`:`<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('spark')} APRÈS LE BAC, CAP SUR ISRAËL</div><h1>Des études qui<br><em>vous ressemblent.</em></h1><p>Explorez les cursus, comprenez les voies d’accès et construisez votre projet, un repère à la fois.</p></div>${heroArt()}</section>`;
    const domains=[...new Set(DATA.courses.map(c=>c.domain))];
    return `${intro}${notice()}${!inst&&!fav&&!getInst(filters.institution)?.courseCoverage?`<div class="directory-callout">${icon('building')}<span>Le répertoire des établissements est plus large que cette sélection de cursus.</span><button class="card-link" data-action="navigate" data-route="etablissements">Explorer les établissements</button></div>`:''}<div class="search-line"><label class="search-box">${icon('search')}<input id="catalogue-search" type="search" placeholder="${inst?'Nom français, hébreu, ancien nom, ville…':'Rechercher un cursus, un établissement…'}" aria-label="${inst?'Rechercher un établissement':'Rechercher un cursus'}" value="${h(filters.q)}" autocomplete="off"></label><button class="button secondary print-button" data-action="print" aria-label="Imprimer ma sélection">${icon('print')}<span>Imprimer</span></button></div><div class="filter-line">${filterSelect('type','Tous les types',['Université','Mihlala'])}${filterSelect('city','Toutes les localités',[...new Set(DATA.institutions.flatMap(places))].sort((a,b)=>a.localeCompare(b,'fr')))}${inst?scopeSelect():`${institutionSelect()}${filterSelect('language','Toutes les langues',[...new Set(DATA.courses.map(c=>c.language))])}`}<button class="reset" data-action="reset-filters">Réinitialiser</button></div>${inst?'':`<div class="domain-line" aria-label="Domaine d’études"><button class="chip ${!filters.domain?'active':''}" data-action="domain" data-value="" aria-pressed="${!filters.domain}">Tous les domaines</button>${domains.map(d=>`<button class="chip ${filters.domain===d?'active':''}" data-action="domain" data-value="${h(d)}" aria-pressed="${filters.domain===d}">${h(d)}</button>`).join('')}</div>`}<div class="results-heading"><h2 id="results-title"></h2><span class="subtle-label">${inst?'Classement alphabétique · Sans classement de qualité':'Ajoutez jusqu’à 3 cursus au comparatif'}</span></div><div id="catalogue-results" aria-live="polite" aria-atomic="false"></div>${fav?'':helpStrip()}${footer()}`;
  }
  function matchesCourse(c){const i=getInst(c.institution);const text=normal([c.title,c.originalTitle,c.faculty,c.domain,c.degree,c.summary,...(c.subjects||[]),...(c.options||[]).map(o=>o.title),i.name,i.short,i.city,i.hebrew,...(i.aliases||[])].join(' '));return(!filters.institution||c.institution===filters.institution)&&(!filters.q||text.includes(normal(filters.q)))&&(!filters.type||filters.type===i.kind)&&(!filters.city||places(i).includes(filters.city))&&(!filters.language||filters.language===c.language)&&(!filters.domain||filters.domain===c.domain)&&(route!=='favoris'||favorites.has(c.id));}
  function updateCatalogue(){
    const inst=route==='etablissements';
    const list=inst?DATA.institutions.filter(i=>inScope(i)&&(!filters.q||normal([i.name,i.short,i.city,i.kind,i.hebrew,i.initials,...(i.aliases||[]),...places(i)].join(' ')).includes(normal(filters.q)))&&(!filters.type||filters.type===i.kind)&&(!filters.subtype||filters.subtype===i.subtype)&&(!filters.city||places(i).includes(filters.city))).sort((a,b)=>a.short.localeCompare(b.short,'fr')):DATA.courses.filter(matchesCourse);
    const title=document.getElementById('results-title');if(!title)return;
    title.innerHTML=`${inst?(filters.subtype||'Les établissements'):route==='favoris'?'Vos favoris':'Les cursus à explorer'} <span>${list.length} ${inst?(list.length===1?'établissement':'établissements'):'cursus'}${!inst&&filters.institution?` · ${h(getInst(filters.institution)?.short)}`:''}${inst&&filters.scope==='postbac'?' avec premier cycle':''}</span>`;
    if(inst)document.getElementById('directory-summary').innerHTML=directorySummary();
    document.getElementById('catalogue-results').innerHTML=(inst?'':institutionCatalogueBanner())+(list.length?`<div class="course-grid">${list.map(inst?institutionCard:courseCard).join('')}</div>`:emptyState(route==='favoris'&&favorites.size===0?'Votre sélection commence ici.':'Aucun résultat pour ces critères.',route==='favoris'&&favorites.size===0?'Enregistrez un cursus avec le marque-page pour le retrouver ici.':inst?'Essayez un autre nom ou élargissez le niveau d’études et les filtres.':'Essayez un autre mot ou élargissez vos filtres.',route==='favoris'&&favorites.size===0?'explorer':'reset'));
  }
  function courseCard(c){const i=getInst(c.institution),fav=favorites.has(c.id),selected=comparison.includes(c.id);return `<article class="course-card" data-tone="${institutionTone(i)}"><div class="card-top">${monogram(i)}<div class="inst-mini"><strong>${h(i.short)}</strong>${h(i.city)}</div><button class="icon-button ${fav?'saved':''}" data-action="favorite" data-id="${h(c.id)}" aria-label="${fav?'Retirer':'Ajouter'} ${h(c.title)} ${fav?'des':'aux'} favoris" aria-pressed="${fav}">${icon('bookmark')}</button></div><div class="card-category">${h(c.domain)} · ${h(c.degree)}</div><h3>${h(c.title)}</h3><p class="summary">${h(c.summary)}</p>${c.optionType&&c.optionType!=='Parcours de premier cycle'?`<p class="course-kind">${h(c.optionType)}</p>`:''}<div class="card-meta"><span>${icon('clock')}${h(c.duration)}</span><span>${icon('language')}${h(c.language)}</span></div><div class="card-bottom"><button class="card-link" data-action="course" data-id="${h(c.id)}">Découvrir le cursus</button><button class="compare-toggle ${selected?'selected':''}" data-action="compare-toggle" data-id="${h(c.id)}" aria-pressed="${selected}" aria-label="${selected?'Retirer du comparatif':'Comparer'} ${h(c.title)} à ${h(i.short)}">${icon(selected?'check':'plus')}${selected?'Sélectionné':'Comparer'}</button></div></article>`;}
  function institutionCard(i){const n=DATA.courses.filter(c=>c.institution===i.id).length;return `<article class="course-card institution-card" data-tone="${institutionTone(i)}"><div class="card-top">${monogram(i)}<div class="inst-mini">${icon('pin')} ${h(i.city)}</div></div><span class="type-badge" data-tone="${institutionTone(i)}">${h(i.subtype||i.kind)}</span><h3>${h(i.name)}</h3>${i.hebrew?`<p class="institution-hebrew" lang="he" dir="rtl">${h(i.hebrew)}</p>`:''}<p class="summary">${h(i.description)}</p><p class="institution-coverage">${i.postbac===false?'Cycles supérieurs · hors post-bac':n?`${n} ${i.courseCoverage?'parcours et options recensés':n===1?'fiche cursus documentée':'fiches cursus documentées'}`:'Cursus à documenter dans l’application'}</p><div class="card-bottom"><button class="card-link" data-action="institution" data-id="${h(i.id)}">Fiche établissement</button>${source(i.url,'Site officiel')}</div></article>`;}
  function emptyState(title,text,action){return `<div class="empty">${icon('search')}<h3>${h(title)}</h3><p>${h(text)}</p><button class="button secondary" data-action="${action==='explorer'?'navigate':'reset-filters'}" data-route="explorer">${action==='explorer'?'Explorer les cursus':'Effacer les filtres'}</button></div>`;}
  function helpStrip(){return `<section class="help-strip">${icon('chat')}<div><h3>Et si vous en parliez avec quelqu’un sur place ?</h3><p>Découvrez la mise en relation envisagée avec un étudiant francophone, avec l’appui du CNEF.</p></div><button class="button secondary" data-action="contact">Découvrir le principe</button></section>`;}
  function toggleFavorite(id){if(!validIds.has(id))return;const was=favorites.has(id);was?favorites.delete(id):favorites.add(id);writeStore('favorites',[...favorites]);toast(was?'Cursus retiré des favoris':'Cursus ajouté à vos favoris');document.getElementById('favorite-count').textContent=favorites.size;if(['explorer','favoris','etablissements'].includes(route))updateCatalogue();if(activeCourse&&document.getElementById('detail-dialog').open)openCourse(activeCourse,activeTab);}
  function toggleComparison(id){if(!validIds.has(id))return;if(comparison.includes(id))comparison=comparison.filter(v=>v!==id);else if(comparison.length>=3){toast('Vous pouvez comparer jusqu’à 3 cursus. Retirez une sélection.');return;}else comparison.push(id);writeStore('comparison',comparison);renderCompareBar();if(['explorer','favoris'].includes(route))updateCatalogue();if(activeCourse&&document.getElementById('detail-dialog').open)openCourse(activeCourse,activeTab);}
  function renderCompareBar(){const container=document.getElementById('comparison-area');if(!container)return;container.innerHTML=comparison.length?`<div class="compare-bar">${icon('compare')}<div><strong>${comparison.length} cursus ${comparison.length>1?'sélectionnés':'sélectionné'}</strong><small>Comparez les contenus et les repères essentiels.</small></div><button class="button primary" data-action="compare-open" ${comparison.length<2?'disabled':''}>Comparer${comparison.length>1?' les '+comparison.length+' cursus':''}</button><button class="icon-button" data-action="compare-clear" aria-label="Vider le comparatif">${icon('close')}</button></div>`:'';}
  function openCompare(){if(comparison.length<2)return;const list=comparison.map(getCourse).filter(Boolean),dialog=document.getElementById('compare-dialog');const row=(label,fn)=>`<tr><th scope="row">${label}</th>${list.map(c=>`<td>${fn(c)}</td>`).join('')}</tr>`;dialog.innerHTML=`${closeButton('compare-dialog')}<div class="eyebrow">${icon('compare')} CHOISIR AVEC DES REPÈRES</div><h2 id="compare-title">Votre comparatif de cursus</h2><p>Un premier regard côte à côte. Les conditions précises restent à confirmer auprès des admissions.</p><div class="compare-scroll"><table class="compare-table"><thead><tr><th scope="col">Vos critères</th>${list.map(c=>`<th scope="col">${monogram(getInst(c.institution))}${h(c.title)}<span class="table-inst">${h(getInst(c.institution).short)}</span></th>`).join('')}</tr></thead><tbody>${row('Ville',c=>h(getInst(c.institution).city))}${row('Établissement',c=>h(getInst(c.institution).kind==='Mihlala'?'Mihlala académique':'Université'))}${row('Diplôme',c=>h(c.degree))}${row('Durée annoncée',c=>h(c.duration))}${row('Langue',c=>h(c.language))}${row('Matières à découvrir',c=>`<ul>${c.subjects.map(s=>`<li>${h(s)}</li>`).join('')}</ul>`)}${row('Admission avec le bac français',()=>'<span class="footnote">Conditions du cursus à faire confirmer pour la rentrée visée.</span>')}${row('Frais de scolarité',()=>'<span class="footnote">Non renseignés dans cette ébauche.</span>')}${row('En savoir plus',c=>`<button class="button soft" data-action="course-from-compare" data-id="${h(c.id)}">Ouvrir la fiche</button>`)}${row('Ma sélection',c=>`<button class="button secondary" data-action="favorite" data-id="${h(c.id)}">${icon('bookmark')}${favorites.has(c.id)?'En favoris':'Garder ce cursus'}</button>`)}</tbody></table></div><p class="footnote" style="margin-top:20px">Comparatif personnel enregistré sur cet appareil. Aucun classement des établissements n’est établi.</p><button class="button secondary" data-action="print">${icon('print')} Imprimer le comparatif</button>`;show(dialog);}
  function closeButton(id){return `<button class="icon-button dialog-close" data-action="close-dialog" data-id="${id}" aria-label="Fermer">${icon('close')}</button>`;}
  function show(dialog){if(!dialog.open)dialog.showModal();}
  function termButton(id,label){const term=DATA.glossary.find(t=>t.id===id)||DATA.glossary.find(t=>normal(t.term).includes(normal(label)));return term?`<button class="term-link" data-action="term" data-id="${h(term.id)}">${h(label||term.term)}</button>`:h(label||id);}
  function openCourse(id,tab='course'){
    const c=getCourse(id);if(!c)return;activeCourse=id;activeTab=tab;const i=getInst(c.institution),fav=favorites.has(id),comp=comparison.includes(id),dialog=document.getElementById('detail-dialog');
    dialog.dataset.tone=institutionTone(i);
    const programmeSources=`${source(c.source,'Voir le programme officiel')}${c.catalogueSource?`<div class="programme-source">${source(c.catalogueSource,'Tableau officiel des parcours 2026–2027')}</div>`:''}`;
    let body='';
    if(tab==='course')body=`<h3>Le cursus en quelques mots</h3><p>${h(c.summary)}</p><dl class="fact-rows"><div class="fact-row"><dt>Diplôme</dt><dd>${h(c.degree)}</dd></div><div class="fact-row"><dt>Durée annoncée</dt><dd>${h(c.duration)}</dd></div><div class="fact-row"><dt>Langue d’enseignement</dt><dd>${h(c.language)}</dd></div><div class="fact-row"><dt>Ville</dt><dd>${h(i.city)}</dd></div>${c.faculty?`<div class="fact-row"><dt>Faculté / domaine</dt><dd>${h(c.faculty)}</dd></div>`:''}${c.optionType?`<div class="fact-row"><dt>Type de parcours</dt><dd>${h(c.optionType)}</dd></div>`:''}${c.checkedOn?`<div class="fact-row"><dt>Vérification documentaire</dt><dd>${h(new Date(c.checkedOn+'T12:00:00').toLocaleDateString('fr-FR'))}</dd></div>`:''}</dl>${c.note?`<div class="inline-banner">${h(c.note)}</div>`:''}<h3>${h(c.subjectsLabel||'Les matières à découvrir')}</h3><ul>${c.subjects.map(s=>`<li>${h(s)}</li>`).join('')}</ul>${c.options?.length?`<h3>Options et approfondissements internes</h3><ul class="course-options">${c.options.map(o=>`<li><strong>${h(o.title)}</strong>${o.text?`<p>${h(o.text)}</p>`:''}<div>${source(o.source,'Détail officiel')}</div></li>`).join('')}</ul>`:''}<p class="footnote">Présentation abrégée pour cette maquette. Le programme détaillé, les options et le campus sont à consulter sur le site de l’établissement.</p>${programmeSources}<div class="soft-note">${icon('info')}<p>Les frais de scolarité et le calendrier ne sont pas encore renseignés dans cette ébauche.</p></div>`;
    if(tab==='admissions')body=`<h3>Préparer les bonnes vérifications</h3><p>Les conditions précises de ce cursus pour un titulaire du bac français ne sont pas encore renseignées dans la maquette.</p><ul><li>Reconnaissance du bac, spécialités et notes prises en compte.</li><li>Voies d’accès prévues et rôle du ${termButton('psychometrique','psychométrique')} ou d’autres examens acceptés.</li><li>Niveau d’hébreu et éventuel ${termButton('yael','YAEL / YAELNET')}.</li><li>Niveau d’anglais et test accepté par l’établissement.</li><li>Préparation éventuelle et reconnaissance de la ${termButton('mechina','mechina')} choisie.</li><li>Documents, échéances et éventuelles conditions complémentaires.</li></ul><div class="soft-note">${icon('info')}<p>Une préparation doit être choisie en fonction du cursus visé. Sa reconnaissance et les conditions de passage sont à vérifier auprès des admissions.</p></div>${source(c.source,'Vérifier auprès de l’établissement')}<div style="margin-top:20px"><button class="button secondary" data-action="navigate-close" data-route="mehinot">${icon('cap')} Découvrir les mehinot</button></div>`;
    if(tab==='contact')body=`<h3>Comprendre le quotidien de ce cursus</h3><p>Échanger avec un étudiant francophone actuellement inscrit permettrait d’aborder les cours, la charge de travail, l’hébreu et l’adaptation à la vie étudiante.</p><div class="cnef-steps"><div class="cnef-step">${icon('file')}<strong>Votre demande</strong>Le cursus et vos questions.</div><div class="cnef-step">${icon('users')}<strong>Le relais CNEF</strong>Un étudiant du parcours, selon les disponibilités.</div><div class="cnef-step">${icon('chat')}<strong>Un échange</strong>Après accord de l’étudiant.</div></div><p class="footnote">Fonctionnement envisagé, à organiser avec le CNEF. Aucun étudiant disponible n’est présenté dans cette ébauche.</p><button class="button primary" data-action="contact" data-id="${h(c.id)}">Découvrir la demande</button><div style="margin-top:18px">${source('https://www.cnef.org/le-cnef-cest-quoi/','Découvrir le CNEF')}</div>`;
    dialog.innerHTML=`${closeButton('detail-dialog')}<div class="dialog-header"><div class="card-top">${monogram(i)}<div class="inst-mini"><strong>${h(i.name)}</strong>${h(i.city)} · ${h(i.kind==='Mihlala'?'Mihlala académique':'Université')}</div></div><h2 id="detail-title">${h(c.title)}</h2>${c.originalTitle?`<p class="course-original" lang="he" dir="rtl">${h(c.originalTitle)}</p>`:''}<p>${h(c.domain)} · ${h(c.degree)}</p></div><div class="dialog-tabs" aria-label="Rubriques de la fiche"><button class="${tab==='course'?'active':''}" data-action="course-tab" data-value="course" aria-pressed="${tab==='course'}">Le cursus</button><button class="${tab==='admissions'?'active':''}" data-action="course-tab" data-value="admissions" aria-pressed="${tab==='admissions'}">Accès & préparation</button><button class="${tab==='contact'?'active':''}" data-action="course-tab" data-value="contact" aria-pressed="${tab==='contact'}">Échanger</button></div><div class="dialog-content"><div class="dialog-body">${body}</div><aside class="dialog-aside"><h3>Votre projet, pas à pas</h3><button class="button ${fav?'soft':'secondary'} full" data-action="favorite" data-id="${h(c.id)}">${icon('bookmark')}${fav?'Enregistré en favoris':'Garder ce cursus'}</button><button class="button secondary full" data-action="compare-toggle" data-id="${h(c.id)}">${icon('compare')}${comp?'Retirer du comparatif':'Ajouter au comparatif'}</button><button class="button primary full" data-action="contact" data-id="${h(c.id)}">${icon('chat')} Parler de ce cursus</button><p class="footnote">Mise en relation envisagée avec l’appui du CNEF. Démonstration sans transmission.</p></aside></div>`;
    show(dialog);
  }
  function institutionCourseGroups(i,query=''){
    const list=DATA.courses.filter(c=>c.institution===i.id&&(!query||normal([c.title,c.originalTitle,c.faculty,c.domain,c.degree,...(c.subjects||[])].join(' ')).includes(normal(query))));
    if(!list.length)return '<p class="institution-no-result" role="status">Aucun parcours ne correspond à cette recherche.</p>';
    const groups=new Map();for(const c of list){const label=c.faculty||'Les cursus documentés';if(!groups.has(label))groups.set(label,[]);groups.get(label).push(c);}
    return `<p class="institution-list-count" role="status">${list.length} ${list.length===1?'parcours affiché':'parcours affichés'}</p>${[...groups].map(([label,courses])=>`<section class="institution-faculty"><h4>${h(label)} <span>${courses.length}</span></h4><div class="institution-course-list">${courses.map(c=>`<button data-action="institution-course" data-id="${h(c.id)}"><span><strong>${h(c.title)}</strong><small>${h(c.degree)} · ${h(c.duration)}</small></span>${icon('book')}</button>`).join('')}</div></section>`).join('')}`;
  }
  function institutionCoverage(i){const meta=i.courseCoverage;if(!meta)return '';return `<section class="institution-coverage-panel"><h3>Offre de premier cycle · ${h(meta.academicYear)}</h3><p>${h(meta.scope)}</p><p class="footnote">Vérification documentaire : ${h(new Date(meta.checkedOn+'T12:00:00').toLocaleDateString('fr-FR'))}. Les intitulés français sont des traductions de repérage.</p>${source(meta.source,'Tableau officiel des parcours')}${meta.notes?.length?`<details><summary>Comprendre le périmètre du recensement</summary><ul>${meta.notes.map(note=>`<li>${h(note)}</li>`).join('')}</ul></details>`:''}</section>`;}
  function institutionPathways(i){return i.studyPathways?.length?`<section class="institution-pathways"><h3>Voies d’entrée et préparation</h3>${i.studyPathways.map(p=>`<article><h4>${h(p.title)}</h4><p>${h(p.text)}</p>${source(p.source,'Informations officielles')}</article>`).join('')}</section>`:'';}
  function openInstitution(id){
    const i=getInst(id);if(!i)return;const list=DATA.courses.filter(c=>c.institution===id),dialog=document.getElementById('institution-dialog');dialog.dataset.tone=institutionTone(i);dialog.dataset.institution=id;
    dialog.innerHTML=`${closeButton('institution-dialog')}<div class="dialog-header"><div class="card-top">${monogram(i)}<div class="inst-mini"><strong>${h(i.subtype||i.kind)}</strong>${h(i.city)}</div></div><h2 id="institution-title">${h(i.name)}</h2>${i.hebrew?`<p class="institution-hebrew" lang="he" dir="rtl">${h(i.hebrew)}</p>`:''}</div><div class="institution-body"><p>${h(i.description)}</p>${i.courseCoverage?`<details class="institution-source-details"><summary>Catalogue ${h(i.courseCoverage.academicYear)} · Périmètre et sources</summary>${institutionCoverage(i)}</details>`:''}<section class="institution-courses"><h3>${i.courseCoverage?'Les parcours après le bac':'Les cursus dans l’application'}</h3>${list.length?`<p>${list.length} ${i.courseCoverage?'parcours et options recensés, regroupés par faculté ou domaine.':list.length===1?'fiche disponible dans cette première sélection.':'fiches disponibles dans cette première sélection.'}</p><button class="button primary" data-action="institution-catalogue" data-id="${h(i.id)}">Explorer ${list.length>1?'les '+list.length+' parcours':'ce cursus'} dans le catalogue</button>${i.courseCoverage?`<label class="search-box institution-course-search">${icon('search')}<input id="institution-course-search" type="search" aria-label="Rechercher un parcours de cet établissement" placeholder="Informatique, architecture, médecine…" autocomplete="off"></label>`:''}<div id="institution-course-results">${institutionCourseGroups(i)}</div>`:`<p>${i.postbac===false?'Cet établissement est conservé pour comprendre le paysage académique ; il ne correspond pas à une entrée directe après le bac.':'Les cursus de cet établissement ne sont pas encore détaillés dans l’application. Consultez son offre officielle pour explorer les formations proposées.'}</p>`}</section>${institutionPathways(i)}<dl class="fact-rows"><div class="fact-row"><dt>Type d’établissement</dt><dd>${h(i.subtype||i.kind)}</dd></div><div class="fact-row"><dt>Implantation(s) indiquée(s)</dt><dd>${h(i.city)}</dd></div><div class="fact-row"><dt>Périmètre des études</dt><dd>${i.postbac===false?'Cycles supérieurs uniquement':'Premier cycle proposé'}</dd></div><div class="fact-row"><dt>Fiche établissement vérifiée</dt><dd>${h(new Date(i.checkedOn+'T12:00:00').toLocaleDateString('fr-FR'))}</dd></div></dl>${i.scopeNote?`<div class="inline-banner">${h(i.scopeNote)}</div>`:''}${i.aliases?.length?`<p class="footnote"><strong>Autres noms et écritures :</strong> ${i.aliases.map(h).join(' · ')}</p>`:''}<div class="institution-source-actions">${source(i.url,'Explorer le site de l’établissement')}${source(i.registrySource,'Source du recensement')}</div><p class="footnote" style="margin:20px 0 0">Les conditions pour les titulaires du bac français, la langue des cours, les campus et les calendriers sont à vérifier pour chaque cursus. Le recensement d’un établissement ne vaut pas confirmation d’admissibilité.</p></div>`;show(dialog);
  }
  function showInstitutionCourses(id){const c=getCourse(id);if(!c)return;document.getElementById('institution-dialog').close();openCourse(id);}
  function openTerm(id){const t=DATA.glossary.find(x=>x.id===id);if(!t)return;const dialog=document.getElementById('term-dialog');dialog.innerHTML=`${closeButton('term-dialog')}<div class="eyebrow">${icon('book')} COMPRENDRE LES MOTS</div><h2 id="term-title">${h(t.term)}</h2>${t.hebrew?`<span class="hebrew" lang="he">${h(t.hebrew)}</span>`:''}<p><strong>${h(t.short)}</strong></p><p>${h(t.detail)}</p><div class="term-practical"><strong>Pour votre projet</strong><p>${h(t.practical)}</p></div>${source(t.source)}<p class="footnote" style="margin-top:16px;margin-bottom:0">Source consultée pour cette ébauche le 24 novembre 2026. Les modalités d’utilisation et les exigences dépendent de l’établissement, du cursus et de la session concernés.</p>`;show(dialog);}
  function glossaryPage(){const cats=[...new Set(DATA.glossary.map(t=>t.category))];return `<div class="page-heading"><div class="eyebrow">${icon('book')} LE SYSTÈME ISRAÉLIEN, EN CLAIR</div><h1>Les mots pour s’y retrouver.</h1><p>Mechina, psychométrique, sekhem… Des explications en français pour les futurs étudiants et leurs parents.</p></div><div class="search-line"><label class="search-box">${icon('search')}<input id="glossary-search" type="search" placeholder="Un terme, une autre écriture, un mot en hébreu…" aria-label="Rechercher dans le glossaire" value="${h(glossaryQuery)}"></label></div><div class="domain-line"><button class="chip ${!glossaryCategory?'active':''}" data-action="glossary-category" data-value="" aria-pressed="${!glossaryCategory}">Tous les mots</button>${cats.map(c=>`<button class="chip ${glossaryCategory===c?'active':''}" data-action="glossary-category" data-value="${h(c)}" aria-pressed="${glossaryCategory===c}">${h(c)}</button>`).join('')}</div><p id="glossary-count" class="glossary-count" aria-live="polite"></p><div id="glossary-results"></div>${footer()}`;}
  function updateGlossary(){const list=DATA.glossary.filter(t=>(!glossaryCategory||t.category===glossaryCategory)&&(!glossaryQuery||normal([t.term,t.hebrew,...(t.aliases||[]),t.short].join(' ')).includes(normal(glossaryQuery))));document.getElementById('glossary-count').textContent=`${list.length} ${list.length>1?'notions expliquées':'notion expliquée'}`;document.getElementById('glossary-results').innerHTML=list.length?`<div class="glossary-grid">${list.map(t=>`<button class="term-card" data-action="term" data-id="${h(t.id)}"><div class="term-title-line"><h3>${h(t.term)}</h3><span class="hebrew" lang="he">${h(t.hebrew)}</span></div><p>${h(t.short)}</p><small>Comprendre cette notion</small></button>`).join('')}</div>`:`<div class="empty">${icon('book')}<h3>Ce terme reste à ajouter.</h3><p>Essayez une autre écriture ou parcourez les notions déjà présentes.</p><button class="button secondary" data-action="glossary-reset">Voir tous les mots</button></div>`;}
  function admissionsPage(){const saved=readStore('checklist',{}),check=typeof saved==='object'&&saved!==null?saved:{};const tasks=['Identifier les cursus et la rentrée qui m’intéressent','Vérifier la prise en compte de mon bac et de mes spécialités','Comprendre les exigences linguistiques et les examens acceptés','Vérifier si une préparation est utile pour mon parcours','Rassembler les documents demandés par chaque établissement','Noter les dates limites et le délai d’obtention des résultats'];return `<div class="page-heading"><div class="eyebrow">${icon('file')} DU PROJET À LA CANDIDATURE</div><h1>Comprendre comment y accéder.</h1><p>Les critères se lisent pour un cursus, une voie d’accès et une rentrée précise. Voici les repères pour préparer vos vérifications.</p></div><div class="page-grid"><article class="info-card"><div class="info-icon">${icon('file')}</div><h3>Votre dossier scolaire</h3><p>Comprendre comment l’établissement prend en compte le bac français, les notes et les spécialités du candidat.</p><button class="card-link" data-action="term-search" data-value="bagrout">Comprendre la bagrout</button></article><article class="info-card"><div class="info-icon orange">${icon('list')}</div><h3>Les examens et les scores</h3><p>Distinguer psychométrique, niveau d’hébreu, niveau d’anglais et éventuel score de sélection de l’établissement.</p><button class="card-link" data-action="navigate" data-route="glossaire">Ouvrir le glossaire</button></article><article class="info-card"><div class="info-icon teal">${icon('cap')}</div><h3>Les voies de préparation</h3><p>Explorer les mehinot et vérifier leur adéquation au cursus visé, ainsi que les conditions pour poursuivre après la préparation.</p><button class="card-link" data-action="navigate" data-route="mehinot">Explorer les mehinot</button></article></div><div class="two-cols section-block"><section class="checklist"><h3>Ma liste de préparation</h3><p>À adapter à chaque établissement. Votre progression reste sur cet appareil.</p>${tasks.map((task,j)=>`<label class="check-row"><input type="checkbox" data-check="${j}" ${check[j]?'checked':''}><span>${h(task)}</span></label>`).join('')}</section><section class="cnef-panel"><div class="info-icon teal">${icon('chat')}</div><h3>Les bonnes questions aux admissions</h3><p>Préparez un échange précis avec le service concerné :</p><ul style="font-size:14px;color:var(--muted);padding-left:20px"><li>Quelle voie d’accès s’applique à mon dossier français ?</li><li>Quels résultats et documents sont attendus, à quelle date ?</li><li>Les critères se cumulent-ils ou existe-t-il une alternative ?</li><li>Quelles conditions reste-t-il à remplir après une réponse conditionnelle ?</li></ul><div class="soft-note">${icon('info')}<p>Une candidature, une admission conditionnelle et une admission définitive sont des étapes distinctes.</p></div>${source('https://info-overseas.huji.ac.il/application-process','Un exemple officiel de procédure')}<div style="margin-top:20px"><button class="button secondary" data-action="navigate" data-route="explorer">Trouver le cursus concerné</button></div></section></div>${footer()}`;}
  function prepsPage(){return `<div class="page-heading"><div class="eyebrow">${icon('cap')} PRÉPARER LA SUITE</div><h1>Une préparation au service de votre projet.</h1><p>Découvrez quelques mehinot académiques et programmes préparatoires. Le choix se construit à partir du cursus que vous souhaitez rejoindre.</p></div><div class="inline-banner">Un programme préparatoire possède ses propres conditions d’entrée. Les cursus qu’il permet de viser et les résultats exigés ensuite sont à confirmer auprès des établissements.</div><div class="page-grid">${DATA.preps.map(p=>`<article class="info-card prep-card"><div class="info-icon">${icon('cap')}</div><div class="eyebrow">${h(getInst(p.institution)?.short||p.institution)}</div><h3>${h(p.name)}</h3><p>${h(p.text)}</p><div class="tag-row">${p.focus.map(f=>`<span class="tag">${h(f)}</span>`).join('')}</div>${source(p.source,'Découvrir le programme officiel')}</article>`).join('')}</div><div class="two-cols section-block"><section class="checklist"><h3>Avant de choisir une préparation</h3><p>Les points à vérifier pour le cursus qui vous intéresse.</p><ul style="font-size:14px;color:var(--muted);padding-left:20px"><li>Le public visé et les conditions pour entrer.</li><li>Les matières, les langues et le rythme des études.</li><li>La durée, le calendrier, les frais et les aides éventuelles.</li><li>La reconnaissance de cette préparation par le cursus cible.</li><li>Les notes ou examens requis pour poursuivre les études.</li></ul><button class="button soft" data-action="navigate" data-route="explorer">Revenir aux cursus</button></section><section class="cnef-panel"><div class="info-icon teal">${icon('book')}</div><h3>Un mot nouveau ?</h3><p>Le glossaire vous aide à distinguer les préparations académiques, l’apprentissage de la langue et les examens.</p><button class="button secondary" data-action="term-search" data-value="mechina">Comprendre « mechina »</button><div style="margin-top:15px"><button class="card-link" data-action="term-search" data-value="oulpan">Comprendre « oulpan »</button></div></section></div>${helpStrip()}${footer()}`;}
  const budgetDefaults={currency:'EUR',months:'10',tuition:'',housing:'',living:'',other:''};
  function getBudget(){const saved=readStore('budget',{});return {...budgetDefaults,...(saved&&typeof saved==='object'?saved:{})};}
  function budgetField(name,label,hint,budget){return `<label class="field">${label}<input type="number" min="0" max="10000000" step="1" name="${name}" data-budget="${name}" value="${h(budget[name])}" placeholder="À renseigner" inputmode="decimal"><small>${hint}</small></label>`;}
  function parentsPage(){const b=getBudget();return `<section class="hero parent-hero"><div class="hero-copy"><div class="eyebrow">${icon('users')} L’ESPACE PARENTS</div><h1>Accompagner,<br><em>un repère à la fois.</em></h1><p>Comprenez les parcours, posez vos questions et préparez le projet ensemble, même en découvrant le système israélien.</p></div>${heroArt()}</section>${notice()}<div class="page-grid"><article class="info-card"><div class="info-icon">${icon('book')}</div><h3>Comprendre le système</h3><p>Les établissements, les cursus et le vocabulaire des admissions expliqués en français.</p><button class="card-link" data-action="navigate" data-route="glossaire">Commencer par les mots</button></article><article class="info-card"><div class="info-icon orange">${icon('compare')}</div><h3>Comparer ensemble</h3><p>Gardez les cursus qui vous intéressent et regardez leurs contenus et repères côte à côte.</p><button class="card-link" data-action="navigate" data-route="favoris">Retrouver les favoris</button></article><article class="info-card"><div class="info-icon teal">${icon('chat')}</div><h3>Parler du quotidien</h3><p>Découvrez le principe d’un échange avec un étudiant francophone du cursus envisagé.</p><button class="card-link" data-action="contact">La mise en relation envisagée</button></article></div><div class="two-cols section-block"><section class="budget-panel"><div class="eyebrow">${icon('wallet')} ANTICIPER LES DÉPENSES</div><h2>Votre budget prévisionnel</h2><p>Renseignez vos hypothèses dans une seule devise. Aucun tarif ni financement n’est présumé.</p><div class="budget-fields"><label class="field">Devise<select data-budget="currency" aria-label="Devise du budget"><option value="EUR" ${b.currency==='EUR'?'selected':''}>Euro (€)</option><option value="ILS" ${b.currency==='ILS'?'selected':''}>Shekel (₪)</option></select><small>Sans conversion automatique</small></label><label class="field">Mois sur place<input type="number" name="months" data-budget="months" min="1" max="24" step="1" value="${h(b.months)}"><small>Pour la période étudiée</small></label>${budgetField('tuition','Frais d’études','Total pour la période',b)}${budgetField('housing','Logement','Montant par mois',b)}${budgetField('living','Vie quotidienne','Montant par mois',b)}${budgetField('other','Autres dépenses','Voyages, assurance… Total période',b)}</div><div class="budget-total"><div><strong id="budget-total">— €</strong><br><span id="budget-period">Pour la période choisie</span></div><button class="icon-button" data-action="budget-reset" aria-label="Effacer les montants du budget">${icon('close')}</button></div><p class="footnote" style="margin:17px 0 0">Estimation personnelle, avant aides éventuelles. Les montants restent sur cet appareil. Changer de devise efface les montants pour éviter de les confondre.</p></section><section><div class="section-title"><h2>Les questions des parents</h2></div><div class="faq">${DATA.parentFaq.map(f=>`<details><summary>${h(f.question)}</summary><p>${h(f.answer)}</p></details>`).join('')}</div><div class="soft-note">${icon('info')}<p>Pour une réponse sur une situation individuelle, faites confirmer les conditions par le service compétent de l’établissement.</p></div><button class="button secondary" data-action="print">${icon('print')} Imprimer ces repères</button></section></div>${footer()}`;}
  function updateBudget(){const b=getBudget(),costs=['tuition','housing','living','other'].map(k=>Number(b[k])||0);const has=costs.some(v=>v>0),months=Math.max(1,Math.min(24,Number(b.months)||1));const total=costs[0]+(costs[1]+costs[2])*months+costs[3];const el=document.getElementById('budget-total');if(!el)return;const unit=b.currency==='ILS'?'₪':'€';el.textContent=has?new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(total)+' '+unit:'— '+unit;document.getElementById('budget-period').textContent=`Pour ${months} mois · avant aides éventuelles`;}
  function openContact(courseId){const c=getCourse(courseId),i=c?getInst(c.institution):null;const dialog=document.getElementById('contact-dialog');dialog.innerHTML=`${closeButton('contact-dialog')}<div class="eyebrow">${icon('chat')} MISE EN RELATION ENVISAGÉE</div><h2 id="contact-title">Parler à quelqu’un qui suit ce cursus.</h2><p>Le CNEF pourrait rechercher un étudiant francophone actuellement inscrit, puis proposer un échange après son accord.</p><div class="soft-note">${icon('info')}<p><strong>Simulation de demande.</strong> Aucun envoi au CNEF, aucune réservation et aucune conservation des informations saisies dans ce formulaire.</p></div>${c?`<div class="contact-context"><strong>${h(c.title)}</strong>${h(i.name)} · ${h(i.city)}</div>`:''}<form id="contact-form" class="contact-form"><div class="two-cols"><label class="field">Vous êtes<select name="role" required><option value="Futur étudiant" ${audience==='student'?'selected':''}>Futur étudiant</option><option value="Parent" ${audience==='parent'?'selected':''}>Parent</option><option value="Étudiant et parent ensemble">Étudiant et parent ensemble</option></select></label><label class="field">Rentrée envisagée<select name="year" required><option value="2027–2028">2027–2028</option><option value="2028–2029">2028–2029</option><option value="Encore en réflexion">Encore en réflexion</option></select></label></div>${!c?`<label class="field">Cursus qui vous intéresse<select name="course" required><option value="">Choisir un cursus</option>${DATA.courses.map(x=>`<option value="${h(x.id)}">${h(x.title)} · ${h(getInst(x.institution).short)}</option>`).join('')}</select></label>`:`<input type="hidden" name="course" value="${h(c.id)}">`}<label class="field">Vos questions principales<textarea name="questions" required minlength="10" maxlength="1500" placeholder="Par exemple : la place de l’hébreu dans les cours, le rythme de travail, l’adaptation…"></textarea><small>10 caractères minimum. Évitez les informations personnelles dans cette démonstration.</small></label><button class="button primary full" type="submit">Simuler ma demande</button><p class="footnote" style="margin:0">Le traitement des demandes et les disponibilités sont à organiser avec le CNEF. ${source('https://www.cnef.org/le-cnef-cest-quoi/','Son site officiel')}</p></form>`;show(dialog);}
  function contactSuccess(form){const data=new FormData(form),c=getCourse(data.get('course'));const question=String(data.get('questions')||'').trim();if(!c||question.length<10){form.querySelector('textarea').setCustomValidity('Précisez votre question en au moins 10 caractères.');form.reportValidity();return;}const d=document.getElementById('contact-dialog');d.innerHTML=`${closeButton('contact-dialog')}<div class="success-icon">${icon('check')}</div><div class="eyebrow">DÉMONSTRATION TERMINÉE</div><h2 id="contact-title">Voici votre demande d’exemple.</h2><p><strong>Aucune demande n’a été envoyée au CNEF.</strong> Cet écran montre le récapitulatif qui pourrait être proposé avant une vraie mise en relation.</p><div class="contact-context"><strong>${h(c.title)} · ${h(getInst(c.institution).short)}</strong>${h(data.get('role'))} · Rentrée ${h(data.get('year'))}</div><p style="white-space:pre-wrap">${h(question)}</p><button class="button primary" data-action="close-dialog" data-id="contact-dialog">Revenir à mon exploration</button>`;d.querySelector('.dialog-close').focus();}
  function navigate(next){if(!routes[next])return;document.body.classList.remove('menu-open');if(location.hash==='#'+next){route=next;shell();window.scrollTo(0,0);}else location.hash=next;}
  let toastTimeout;
  function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),2900);}
  document.addEventListener('click',event=>{
    if(event.target.closest('a.skip')){event.preventDefault();document.getElementById('main').focus();return;}
    const target=event.target.closest('[data-action]');if(!target)return;
    const {action,id,value,route:next}=target.dataset;
    if(action==='toggle-menu'){const open=document.body.classList.toggle('menu-open');target.setAttribute('aria-expanded',open);target.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');}
    if(action==='close-menu'){document.body.classList.remove('menu-open');document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded','false');}
    if(action==='navigate')navigate(next);
    if(action==='navigate-close'){document.querySelectorAll('dialog[open]').forEach(d=>d.close());navigate(next);}
    if(action==='audience'){audience=value==='parent'?'parent':'student';writeStore('audience',audience);navigate(audience==='parent'?'parents':'etablissements');}
    if(action==='reset-filters'){filters=emptyFilters();if(catalogueFilters[route])catalogueFilters[route]=filters;if(route==='explorer')history.replaceState(null,'','#explorer');renderPage();}
    if(action==='domain'){filters.domain=value;document.querySelectorAll('[data-action="domain"]').forEach(el=>{el.classList.toggle('active',el.dataset.value===value);el.setAttribute('aria-pressed',el.dataset.value===value);});updateCatalogue();}
    if(action==='favorite'){toggleFavorite(id);if(document.getElementById('compare-dialog').open)openCompare();}
    if(action==='compare-toggle')toggleComparison(id);
    if(action==='compare-clear'){comparison=[];writeStore('comparison',comparison);renderCompareBar();if(['explorer','favoris'].includes(route))updateCatalogue();if(activeCourse&&document.getElementById('detail-dialog').open)openCourse(activeCourse,activeTab);}
    if(action==='compare-open')openCompare();
    if(action==='course')openCourse(id);
    if(action==='course-tab')openCourse(activeCourse,value);
    if(action==='course-from-compare'){document.getElementById('compare-dialog').close();openCourse(id);}
    if(action==='institution')openInstitution(id);
    if(action==='institution-course')showInstitutionCourses(id);
    if(action==='institution-catalogue'){document.getElementById('institution-dialog').close();catalogueFilters.explorer={...emptyFilters(),institution:id};filters=catalogueFilters.explorer;const hash='#explorer?institution='+encodeURIComponent(id);if(location.hash===hash){route='explorer';shell();window.scrollTo(0,0);}else location.hash=hash;}

    if(action==='institution-category'){filters.subtype=filters.subtype===value?'':value;filters.type='';document.querySelector('[data-filter="type"]').value='';updateCatalogue();}
    if(action==='term')openTerm(id);
    if(action==='term-search'){const found=DATA.glossary.find(t=>normal([t.term,...(t.aliases||[])].join(' ')).includes(normal(value)));if(found)openTerm(found.id);else{glossaryQuery=value;navigate('glossaire');}}
    if(action==='glossary-category'){glossaryCategory=value;document.querySelectorAll('[data-action="glossary-category"]').forEach(el=>{el.classList.toggle('active',el.dataset.value===value);el.setAttribute('aria-pressed',el.dataset.value===value);});updateGlossary();}
    if(action==='glossary-reset'){glossaryQuery='';glossaryCategory='';renderPage();}
    if(action==='contact')openContact(id);
    if(action==='close-dialog')document.getElementById(id)?.close();
    if(action==='print')window.print();
    if(action==='budget-reset'){writeStore('budget',budgetDefaults);renderPage();toast('Les montants ont été effacés.');}
  });
  document.addEventListener('input',event=>{
    const el=event.target;
    if(el.id==='catalogue-search'){filters.q=el.value;updateCatalogue();}
    if(el.id==='institution-course-search'){const i=getInst(document.getElementById('institution-dialog').dataset.institution);if(i)document.getElementById('institution-course-results').innerHTML=institutionCourseGroups(i,el.value);}
    if(el.id==='glossary-search'){glossaryQuery=el.value;updateGlossary();}
    if(el.dataset.budget&&el.dataset.budget!=='currency'){const b=getBudget();let v=el.value;if(v!==''&&Number(v)<0){v='0';el.value=v;}if(el.dataset.budget==='months'&&Number(v)>24){v='24';el.value=v;}if(Number(v)>10000000){v='10000000';el.value=v;}b[el.dataset.budget]=v;writeStore('budget',b);updateBudget();}
    if(el.name==='questions')el.setCustomValidity('');
  });
  document.addEventListener('change',event=>{const el=event.target;if(el.dataset.filter){filters[el.dataset.filter]=el.value;if(el.dataset.filter==='institution'&&route==='explorer')history.replaceState(null,'','#explorer'+(el.value?'?institution='+encodeURIComponent(el.value):''));if(el.dataset.filter==='type')filters.subtype='';if(el.dataset.filter==='institution'){renderPage();document.querySelector('[data-filter="institution"]')?.focus();}else updateCatalogue();}if(el.dataset.check!==undefined){const old=readStore('checklist',{});const checks=old&&typeof old==='object'?old:{};checks[el.dataset.check]=el.checked;writeStore('checklist',checks);}if(el.dataset.budget==='currency'){const b=getBudget();writeStore('budget',{...budgetDefaults,months:b.months,currency:el.value});renderPage();toast('Nouvelle devise : renseignez les montants dans cette devise.');}});
  document.addEventListener('submit',event=>{if(event.target.id==='contact-form'){event.preventDefault();contactSuccess(event.target);}});
  document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}}));
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.body.classList.remove('menu-open');document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded','false');}});
  function routeFromHash(){const [name,query='']=location.hash.slice(1).split('?');const next=routes[name]?name:'etablissements';const params=new URLSearchParams(query);if(next==='explorer'){const id=params.get('institution');catalogueFilters.explorer={...catalogueFilters.explorer,institution:getInst(id)?id:''};}return next;}
  window.addEventListener('hashchange',()=>{route=routeFromHash();if(catalogueFilters[route])filters=catalogueFilters[route];document.body.classList.remove('menu-open');shell();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});});
  route=routeFromHash();
  if(catalogueFilters[route])filters=catalogueFilters[route];
  shell();
})();
